/* 
 * Serial Plotter — Controls frequency of a Sine and Triangle wave
 * using a potentiometer on A0.
 */
int potPin = A0;
float phase = 0.0; // Keeps track of the wave positions smoothly

void setup() {
  Serial.begin(9600);
}

void loop() {
  int potValue = analogRead(potPin);

  // Map pot value (0-1023) to a frequency factor (0.01 to 0.2)
  float frequencyFactor = 0.01 + ((float)potValue / 1023.0) * 0.19;

  // Advance the phase based on the pot setting
  phase += frequencyFactor;
  if (phase >= 2.0 * PI) {
    phase -= 2.0 * PI;
  }

  // 1. Calculate Sine Wave (scaled between 0 and 1023)
  int sine = (int)((sin(phase) + 1.0) * 511.5);

  // 2. Calculate Triangle Wave (scaled between 0 and 1023)
  // Normalizes phase to 0.0 - 1.0 range for the math
  float normPhase = phase / (2.0 * PI); 
  int triangle;
  if (normPhase < 0.5) {
    triangle = (int)(normPhase * 2.0 * 1023.0);         // Rising edge
  } else {
    triangle = (int)((1.0 - normPhase) * 2.0 * 1023.0); // Falling edge
  }

  // Print data formatted for the Serial Plotter
  Serial.print("pot:");
  Serial.print(potValue);
  Serial.print(" sine:");
  Serial.print(sine);
  Serial.print(" triangle:");
  Serial.println(triangle);

  delay(30); // Slightly faster delay for smoother high-frequency viewing
}
